using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class EmployeeRepository(ProjetoIntegradorBackDbContext context):IEmployeeRepository{
public async Task<Result<Employee>> GetPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Employees.Include(x=>x.User).FirstOrDefaultAsync(x=>x.Id==id,ct);return e==null?Result<Employee>.AsFailure(new Failure(404,"Funcionário não encontrado.")):Result<Employee>.AsSuccess(e);}catch(Exception ex){return Result<Employee>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Employee>>> ListPorEstablishmentAsync(Guid id,CancellationToken ct=default){try{return Result<IReadOnlyList<Employee>>.AsSuccess(await context.Employees.Where(x=>x.EstablishmentId==id).Include(x=>x.User).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Employee>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Employee>> AddAsync(Employee e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CreatedAt=DateTime.UtcNow;await context.Employees.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Employee>.AsSuccess(e);}catch(Exception ex){return Result<Employee>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Employee>> UpdateAsync(Employee e,CancellationToken ct=default){try{context.Employees.Update(e);await context.SaveChangesAsync(ct);return Result<Employee>.AsSuccess(e);}catch(Exception ex){return Result<Employee>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> AlterarVinculoAsync(Guid id,bool ativo,CancellationToken ct=default){try{var e=await context.Employees.FindAsync(new object[]{id},ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Funcionário não encontrado."));e.IsActive=ativo;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Vínculo atualizado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}}